WITH latest_match AS (SELECT s.*, top1.inventory_last_restock, top1.inventory_quantity FROM stores s JOIN LATERAL (SELECT c.last_restock AS inventory_last_restock, c.quantity AS inventory_quantity FROM inventory c WHERE c.store_id = s.id ORDER BY c.quantity DESC, c.id DESC LIMIT 1) top1 ON TRUE) SELECT region, CASE WHEN sqft >= 16882 THEN 'HIGH' ELSE 'LOW' END AS sqft_tier, PERCENTILE_APPROX(sqft, 0.95) AS sqft_p95, COUNT_IF(region = 'East') AS east_events, PERCENTILE_APPROX(inventory_quantity, ARRAY(0.25, 0.5, 0.75)) AS inventory_quantity_quartiles, AVG(sqft) FILTER (WHERE city = 'Berlin') AS berlin_avg_sqft, SORT_ARRAY(COLLECT_SET(city)) AS city_list, MAX(inventory_quantity) FILTER (WHERE city = 'Singapore') AS singapore_max_inventory_quantity FROM latest_match GROUP BY region, CASE WHEN sqft >= 16882 THEN 'HIGH' ELSE 'LOW' END HAVING MAX(inventory_quantity) FILTER (WHERE city = 'Singapore') > 0 ORDER BY east_events DESC
